### Required `acquire-tfstate/terragrunt.hcl` Template

```hcl
# iac/terraform/deployments/aws/<env-short-name>/acquire-tfstate/terragrunt.hcl

locals {
  env_locals = read_terragrunt_config(find_in_parent_folders("locals-env.hcl"))
}

terraform {
  source = "git::ssh://git@github.com/mygainwell/pfe-terraform-modules.git//acquire-tfstate?ref=v1.0.0"
}

inputs = {
  environment       = local.env_locals.locals.env_short_name
  region_context    = local.env_locals.locals.cloud_locals.locals.primary_region
}
```

