[standards/infrastructure/iac/STD-INFRA-IAC-011-environment-scaffolding.md#required-deploy-commonterragrunthcl-template]

### Required `deploy-common/terragrunt.hcl` Template

```hcl
# iac/terraform/deployments/aws/<env-short-name>/deploy-common/terragrunt.hcl

include "root" {
  path = find_in_parent_folders("common-includes.hcl")
}

dependency "acquire_tfstate" {
  config_path = "../acquire-tfstate"

  mock_outputs_allowed_terraform_commands = ["validate", "plan"]
  mock_outputs = {
    vpc_id     = "vpc-mock"
    subnet_ids = ["subnet-mock-1", "subnet-mock-2"]
  }
}

dependencies {
  paths = [
    "./security-groups.hcl",
    "./security-group-rules.hcl"
  ]
}
```
